cols = [[], [], [], []]

for col_idx, art_id, url, author, avatar_url, initial in cards_raw:
    thumb_filename = f"thumb_{art_id}.avif"
    thumb_local = f"public/community_home/thumbnails/{thumb_filename}"
    thumb_rel = f"/community_home/thumbnails/{thumb_filename}"
    
    if not download_image(url, thumb_local):
        thumb_rel = url
        
    avatar_rel = None
    if avatar_url:
        ext = "png" if ".png" in avatar_url else "jpg"
        clean_id = re.sub(r'[^a-zA-Z0-9]', '_', art_id)
        avatar_filename = f"avatar_{clean_id}.{ext}"
        avatar_local = f"public/community_home/avatars/{avatar_filename}"
        avatar_rel = f"/community_home/avatars/{avatar_filename}"
        if not download_image(avatar_url, avatar_local):
            avatar_rel = avatar_url
            
    card = {
        "id": art_id,
        "src": thumb_rel,
        "author": author,
        "initial": initial or author[0].upper()
    }
    if avatar_rel:
        card["avatar"] = avatar_rel
        
    cols[col_idx].append(card)

# Load existing strip if available
strip_items = []
try:
    with open('public/community_home_data.json') as f:
        existing = json.load(f)
        if "strip" in existing:
            strip_items = existing["strip"]
except Exception:
    pass

result = {
    "strip": strip_items,
    "col1": cols[0],
    "col2": cols[1],
    "col3": cols[2],
    "col4": cols[3]
}

with open('public/community_home_data.json', 'w', encoding='utf-8') as f:
    json.dump(result, f, indent=2, ensure_ascii=False)

print(f"Saved {sum(len(c) for c in cols)} cards across 4 columns to public/community_home_data.json")
